using Chaos.Domain.Summaries;
using Chaos.Domain.Tasks;

namespace Chaos.Application.Contracts;

public enum SummaryTrigger
{
    Scheduled = 0,
    /// <summary>A period missed while Chaos was closed, generated once at the next start.</summary>
    CatchUp = 1,
    /// <summary>Generated or regenerated by hand.</summary>
    Manual = 2,
}

/// <summary>
/// One stored revision of a plain summary (PLAN §5 Summaries, §12). The facts are captured
/// once and never recomputed, so a later rename, move or deletion does not rewrite the journal.
/// </summary>
public sealed record SummaryRecord
{
    public required string Id { get; init; }
    public required string ProfileId { get; init; }
    public required SummaryKind Kind { get; init; }
    public required DateOnly PeriodStart { get; init; }
    public required DateOnly PeriodEnd { get; init; }
    public required long Revision { get; init; }
    public required DateTimeOffset PeriodStartUtc { get; init; }
    public required DateTimeOffset PeriodEndUtc { get; init; }
    /// <summary>How far the facts reach; before the period end the summary is partial ("through HH:mm").</summary>
    public required DateTimeOffset CapturedThroughUtc { get; init; }
    public required string ZoneId { get; init; }
    public required SummaryTrigger Trigger { get; init; }
    /// <summary>Versioned JSON of <see cref="SummaryFacts"/>.</summary>
    public required string FactsJson { get; init; }
    public required int ResourceVersion { get; init; }
    public required DateTimeOffset GeneratedAtUtc { get; init; }
    public DateTimeOffset? PromptAtUtc { get; init; }
    public DateTimeOffset? PromptSeenAtUtc { get; init; }

    [System.Text.Json.Serialization.JsonIgnore]
    public bool IsPartial => CapturedThroughUtc < PeriodEndUtc;
}

/// <summary>A task as the summary captured it: title and list name at generation time.</summary>
public sealed record SummaryTaskFact(
    string TaskId,
    string Title,
    string ContainerId,
    string ContainerName,
    ContainerKind ContainerKind,
    TaskItemStatus Status,
    TaskPriority Priority,
    DateOnly? PlannedDate,
    DateOnly? DueDate,
    TimeOnly? DueTime,
    int? EstimateMinutes);

/// <summary>
/// One completion event in the period (from append-only history). A task completed and then
/// reopened keeps its event, annotated <see cref="ReopenedAfter"/>; <see cref="StillDone"/>
/// says whether it was done when the summary was captured.
/// </summary>
public sealed record CompletionFact(SummaryTaskFact Task, DateTimeOffset CompletedAtUtc, bool ReopenedAfter, bool StillDone);

/// <summary>How far a project moved: Done over noncancelled top-level tasks at the period start and at capture.</summary>
public sealed record ProjectProgressFact(string ProjectId, string Name, int DoneBefore, int CountedBefore, int DoneAfter, int CountedAfter);

public enum UnfinishedSource
{
    /// <summary>Chosen for My Day on that date.</summary>
    MyDay = 0,
    /// <summary>Assigned to that date (or week) in the confirmed weekly plan.</summary>
    Week = 1,
    /// <summary>The task's own planned date fell in the period.</summary>
    Planned = 2,
}

public sealed record UnfinishedFact(SummaryTaskFact Task, UnfinishedSource Source);

public sealed record WaitingFact(SummaryTaskFact Task, string? Person, DateTimeOffset? FollowUpDueAtUtc);

public sealed record DiaryFact(string EntryId, string TaskId, string TaskTitle, DateTimeOffset EntryAtUtc, string Excerpt);

public enum SuggestionSource
{
    Overdue = 0,
    Unfinished = 1,
    DueNext = 2,
    PlannedNext = 3,
}

public sealed record SuggestionFact(SummaryTaskFact Task, SuggestionSource Reason);

public sealed record GoalFact(string GoalId, string Title, WeekGoalOutcome Outcome, int DoneCount, int CountedCount);

/// <summary>Progress against the confirmed weekly plan at capture: assigned tasks done/cancelled and goal progress.</summary>
public sealed record WeekProgressFact(DateOnly WeekStart, long Revision, int AssignedCount, int DoneCount, int CancelledCount, IReadOnlyList<GoalFact> Goals);

/// <summary>A follow-up due in the period (morning summary).</summary>
public sealed record FollowUpFact(SummaryTaskFact Task, string? Person, DateTimeOffset DueAtUtc);

/// <summary>
/// The structured facts of one summary (PLAN §12). Rendering is lists and counts in the UI
/// resource language; there is no generated narrative. Lists not used by a kind are empty.
/// </summary>
public sealed record SummaryFacts
{
    /// <summary>Completion events in the period, oldest first.</summary>
    public IReadOnlyList<CompletionFact> Completions { get; init; } = [];
    public IReadOnlyList<ProjectProgressFact> Projects { get; init; } = [];
    /// <summary>Planned but not finished at capture.</summary>
    public IReadOnlyList<UnfinishedFact> Unfinished { get; init; } = [];
    public IReadOnlyList<WaitingFact> Waiting { get; init; } = [];
    /// <summary>Open tasks due in the next period: tomorrow (daily), next week (weekly), today (morning).</summary>
    public IReadOnlyList<SummaryTaskFact> Deadlines { get; init; } = [];
    public IReadOnlyList<DiaryFact> DiaryUpdates { get; init; } = [];
    public int DiaryUpdateCount { get; init; }
    /// <summary>A suggested start for the next My Day (daily) or week (weekly).</summary>
    public IReadOnlyList<SuggestionFact> Suggested { get; init; } = [];
    public WeekProgressFact? Week { get; init; }
    /// <summary>Morning: the day's selected and week-planned tasks.</summary>
    public IReadOnlyList<SummaryTaskFact> Selected { get; init; } = [];
    public int OverdueCount { get; init; }
    public IReadOnlyList<FollowUpFact> FollowUps { get; init; } = [];
    /// <summary>True when every list above is empty: shown as a quiet period, not an error.</summary>
    [System.Text.Json.Serialization.JsonIgnore]
    public bool IsQuiet =>
        Completions.Count == 0 && Projects.Count == 0 && Unfinished.Count == 0 && Waiting.Count == 0 && Deadlines.Count == 0
        && DiaryUpdates.Count == 0 && Suggested.Count == 0 && Selected.Count == 0 && OverdueCount == 0 && FollowUps.Count == 0
        && (Week is null || Week.AssignedCount == 0 && Week.Goals.Count == 0);
}
